from pathlib import Path
from PIL import Image,ImageOps,ImageDraw,ImageFont
import json,base64,io,html,hashlib
R=Path(__file__).resolve().parents[1];folder=R.name;model='ai-skunkworks-robot-skunk';a=json.loads((R/'audit.json').read_text());v=json.loads((R/'verification.json').read_text())
fontpath='/System/Library/Fonts/Supplemental/Arial.ttf';font=ImageFont.truetype(fontpath,25);small=ImageFont.truetype(fontpath,20)
views=[('hero','Three-quarter view','The long muzzle, goggles, broad chest shield, piston gloves and tall crest in the first completed interpretation.'),('side','Side profile','The S-shaped tail and backpack follow reference B; the tail cross-section and rear construction are inferred.'),('front','Front view','Symmetric armor and gloves; there is no supplied front orthographic drawing, so this view exposes inferred width.'),('rear','Rear quarter','Backpack, shoulder hoses and tail stripe. The hidden rear surfaces are an interpretation, not reference-confirmed.'),('head','Face and goggles','A mechanical eye, curved smile, long muzzle and swept crest; the crest remains more fan-like than the drawing.'),('gauntlet','Mechanical glove','Three curled fingers, knuckle caps, thumb, hydraulic barrel, cable and forearm fin; these are static parts.')]
comparisons=[]
for letter,key in [('A','hero'),('B','side')]:
 ref=Image.open(R/'references'/f'reference-{letter}.png').convert('RGB');mask=ref.convert('L').point(lambda x:255 if x>100 else 0);ref=ref.crop(mask.getbbox())
 render=Image.open(R/'renders'/f'{key}.png').convert('RGB');canvas=Image.new('RGB',(1600,1120),'#f2f0e9');d=ImageDraw.Draw(canvas)
 for img,x,label in [(ref,20,f'REFERENCE {letter} — supplied line drawing'),(render,810,'CURRENT — actual Blender render')]:
  im=ImageOps.contain(img,(770,990));canvas.paste(im,(x+(770-im.width)//2,65+(990-im.height)//2));d.text((x+10,20),label,font=font,fill='#202020')
 d.text((30,1070),'Camera and pose are approximate. Materials, hidden depth and symmetry are inferred.',font=small,fill='#202020')
 path=R/'compare'/f'reference-{letter}-vs-current.jpg';canvas.save(path,quality=90);comparisons.append((f'Reference {letter} comparison',path.relative_to(R).as_posix(),f'Supplied reference {letter} left; actual {key} render right. Approximate alignment; no claim of exact reconstruction.'))
stat=f"{a['mesh_objects']} meshes + {a['curve_objects']} curves · {a['evaluated_triangles']:,} evaluated triangles · {a['materials']} materials · {' × '.join(f'{x:.3f}' for x in a['dimensions'])} design units (XYZ) · Blender {a['blender_version']} · Codex"
limits='''First interpretation, not a finished likeness. The crest is more fan-like and the face more mechanical than the drawings; the boots are smoother, the armor and glove articulation are simplified, and the pose differs. Black/ivory materials and optical accent colors are proposed because the supplied references are uncolored line art. No rear, front or top drawing establishes depth, so symmetry, rear surfaces and cross-sections are inferred. Arbitrary design units, no verified real-world scale. No rig, animation, working hydraulics or game-ready retopology. Parts overlap; no watertight or 3D-printing suitability claim. Human review: Professor Bear — pending.'''
built='''Builder: Codex. Method: scripted Blender mesh, curve and loft construction from two user-supplied drawings; three documented visual comparison rounds. Tools: Blender 4.2.0 (Cycles and built-in glTF exporter), Python and Pillow for packaging. Build date: October 21, 2026. Reference drawing authorship was not supplied; reference images provided by Nik Bear Brown. Human review: Professor Bear — pending.'''
base=f'https://github.com/nikbearbrown/csye-7270-building-virtual-environments/raw/main/blender/{folder}/';pages=f'https://nikbearbrown.github.io/csye-7270-building-virtual-environments/blender/{folder}/';fallback='https://htmlpreview.github.io/?'+base+'index.html'
readme=f'# AI Skunkworks robot skunk\n\nA first stylized 3D interpretation of two supplied robot-skunk drawings, with inferred depth and materials.\n\n{stat}\n'
for key,title,caption in views:
 readme+=f'\n## {title}\n\n{caption}\n\n![{title}](renders/{key}.png)\n\n[Full-size image](renders/{key}.png)\n'
for title,path,caption in comparisons:readme+=f'\n## {title}\n\n{caption}\n\n![{title}]({path})\n\n[Full-size comparison]({path})\n'
readme+='\n## Film\n\nCompanion film: coming soon\n<!-- FILM_URL -->\n\n## Downloads\n\n| File | Size | Purpose |\n|---|---|---|\n'
for ext,purpose in [('blend','Editable scene, separated parts, materials, lights and six cameras'),('glb','Character-only evaluated geometry and PBR material colors; no image textures')]:
 p=R/f'{model}.{ext}';readme+=f'| [{p.name}]({base}{p.name}) | {p.stat().st_size/1e6:.2f} MB | {purpose} |\n'
readme+=f'''\n## Import\n\nOpen the `.blend` in Blender 4.2 or later (saved and reopened in 4.2.0). For the GLB, use File → Import → glTF 2.0. The native file preserves editable parts and modifiers; the GLB bakes evaluated geometry, including curve cables. Studio lights, cameras, floor and modifier editability are not exported.\n\n## Offline review viewer\n\nDownload [index.html](index.html) and open it in a browser. Its images, styles and controls are embedded; no network is needed for the gallery. It is an image review viewer, not a live 3D orbit.\n\n[Pages viewer]({pages}) · [HTML preview fallback]({fallback}). Pages availability must be checked separately.\n\n## Built by\n\n{built}\n\n## Limitations\n\n{limits}\n'''
(R/'README.md').write_text(readme)
(R/'BUILD_NOTES.md').write_text(f'''# Build notes\n\n{stat}\n\n## Reference and method\n\nTwo supplied PNG line drawings, preserved in `references/`. Reference A is a three-quarter standing view; B is an approximate side view. They are not calibrated orthographic blueprints. Front is −Y, width is X, height is Z. The model uses named editable parts; custom lofts make the muzzle and tail. Armor, joints, knuckles and hydraulic forms are separate meshes. Curves supply cables and panel accents. The mane uses a convex custom silhouette mesh. Material colors are invented for readability, not sampled as design evidence.\n\n## Auditable comparison rounds\n\n1. Draft hero and side renders (`compare/round-01/`). Review found a flat saw-blade crest, buried optical eyes, overly bulbous paired chest plates and small gloves.\n2. Revised hero and side (`compare/round-02/`). Convex crest, exposed optics and larger gauntlets improved the read. The paired chest plates became too small and floating; replaced with one broad tapered shield. The crest still reads more like a fan than the drawing.\n3. Final six renders and two reference comparisons. The broader chest shield and more side-on hero view show the silhouette and tail better. Recognizable robot-skunk features are present, but organic contours, exact proportions, facial expression and plate shapes remain approximate. Professor Bear has not judged the likeness.\n\n## Validation\n\nNative `.blend` reopened with Blender {v['reopened_with']}. GLB reimported: {v['glb_import_meshes']} meshes, {v['glb_import_triangles']:,} triangles; evaluated native triangle count and dimensions match within 0.0001 design unit. No image textures, skins or animations in GLB. Geometry includes converted native curves. Separate studio excluded. See `audit.json` and `verification.json`. Passing export checks does not establish likeness, printability, animation readiness or manifold topology.\n\n## Known limitations\n\n{limits}\n\n{built}\n\n## Reproduce\n\nRun Blender 4.2 in background with `--python scripts/build.py`. Use `-- --draft` for two smaller previews, or omit it for all six final renders. Then run `scripts/verify.py` with Blender and `scripts/package.py` with Python/Pillow. Script paths resolve relative to the package.\n''')
def uri(path):
 im=Image.open(path).convert('RGB');im.thumbnail((1100,1100));b=io.BytesIO();im.save(b,format='JPEG',quality=82);return 'data:image/jpeg;base64,'+base64.b64encode(b.getvalue()).decode()
slides=[{'title':title,'caption':caption,'src':uri(R/'renders'/f'{key}.png')} for key,title,caption in views]
cs=[{'title':title,'caption':caption,'src':uri(R/path)} for title,path,caption in comparisons]
css='''*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:17px/1.6 system-ui,sans-serif;--bg:#f0eee7;--fg:#1b2529;--panel:#fff}body.dark{--bg:#11191f;--fg:#e9eae4;--panel:#243038}main{max-width:1200px;margin:auto;padding:28px}h1{font-size:clamp(28px,5vw,48px);line-height:1.1}h2{font-size:26px}.stats{font:14px/1.7 monospace}button,a{color:inherit}a{text-underline-offset:3px}button{background:var(--panel);border:1px solid #7b8587;padding:10px 16px;border-radius:6px;cursor:pointer;font:inherit}button[aria-pressed=true]{outline:3px solid #699394}button:focus-visible,a:focus-visible{outline:3px solid #bb762e}nav,.thumbs{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.stage{margin:0;background:var(--panel);padding:15px}.stage img{display:block;max-width:100%;height:70vh;max-height:850px;object-fit:contain;margin:auto}.thumbs button{padding:5px}.thumbs img{width:105px;height:110px;object-fit:cover}.compare{display:grid;grid-template-columns:1fr 1fr;gap:20px}.compare img{width:100%;height:auto}figcaption{padding:12px 0}footer,section{border-top:1px solid #78848b;margin-top:30px;padding-top:20px}@media(max-width:650px){main{padding:16px}.compare{grid-template-columns:1fr}.stage img{height:auto;max-height:65vh}.thumbs img{width:64px;height:75px}button{padding:8px}}'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Skunkworks robot skunk — Codex</title><style>{css}</style></head><body><main><button id="theme" aria-label="Toggle light and dark theme">Light / dark</button><h1>AI Skunkworks robot skunk</h1><p>First interpretation from two line drawings. Editable, unrigged; hidden depth and colors inferred.</p><p class="stats">{stat}</p><nav id="views" aria-label="Model views"></nav><figure class="stage"><img id="stage" alt=""><figcaption id="caption"></figcaption></figure><div class="thumbs" id="thumbs" aria-label="View thumbnails"></div><p>Use the view buttons, thumbnails, or left/right arrow keys.</p><section><h2>Reference / current</h2><div class="compare">'''
for c in cs:page+=f'<figure><img src="{c["src"]}" alt="{c["title"]}"><figcaption>{c["caption"]}</figcaption></figure>'
page+=f'''</div></section><section><h2>Film and files</h2><p id="film">Companion film: coming soon</p><p><a href="{base}{model}.blend">Download Blender scene</a> · <a href="{base}{model}.glb">Download GLB</a></p><p>Open the native file in Blender 4.2 or later. Import the GLB with File → Import → glTF 2.0. GLB contains evaluated character geometry and PBR colors, without image textures, studio, editable modifiers or a rig.</p></section><section><h2>Built by</h2><p>{built}</p><h2>Limitations and review</h2><p>{limits}</p></section></main><script>const FILM_URL = "";const slides={json.dumps(slides)};let current=0;const nav=document.getElementById('views'),thumbs=document.getElementById('thumbs');function show(i){{current=(i+slides.length)%slides.length;const s=slides[current];document.getElementById('stage').src=s.src;document.getElementById('stage').alt=s.title;document.getElementById('caption').textContent=s.title+' — '+s.caption;[...nav.children].forEach((b,j)=>b.setAttribute('aria-pressed',j===current));}}slides.forEach((s,i)=>{{let b=document.createElement('button');b.textContent=s.title;b.onclick=()=>show(i);nav.append(b);let t=document.createElement('button');t.setAttribute('aria-label',s.title);let img=document.createElement('img');img.src=s.src;img.alt=s.title;t.append(img);t.onclick=()=>show(i);thumbs.append(t);}});document.getElementById('theme').onclick=()=>document.body.classList.toggle('dark');document.addEventListener('keydown',e=>{{if(e.key==='ArrowRight')show(current+1);if(e.key==='ArrowLeft')show(current-1);}});if(FILM_URL){{const a=document.createElement('a');a.href=FILM_URL;a.textContent='Watch companion film';document.getElementById('film').replaceChildren(a);}}show(0);</script></body></html>'''
(R/'index.html').write_text(page)
assert (R/'index.html').stat().st_size<5_000_000
